// Tokens are generated by the user's CAPTCHA challenge and validated by Supabase Auth.
(() => {
  'use strict';
  const config=window.TERRA_CONFIG?.captcha||{};
  let token='',widget=null,loading=null,sequence=0;
  const el=id=>document.getElementById(id);
  const api=()=>config.provider==='turnstile'?window.turnstile:window.hcaptcha;
  function message(text){el('captcha-message').textContent=text;el('captcha-message').hidden=!text;}
  function clear(){token='';if(config.enabled)el('auth-submit').disabled=true;}
  function load(){
    if(api()?.render)return Promise.resolve();
    if(loading)return loading;
    loading=new Promise((resolve,reject)=>{
      const timer=setTimeout(()=>reject(new Error('A verificação demorou para carregar. Recarregue a página.')),20000);
      window.terraCaptchaReady=()=>{clearTimeout(timer);resolve();};
      const script=document.createElement('script');script.async=true;script.defer=true;
      script.src=config.provider==='turnstile'?'https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit&onload=terraCaptchaReady':'https://js.hcaptcha.com/1/api.js?render=explicit&onload=terraCaptchaReady';
      script.onerror=()=>{clearTimeout(timer);reject(new Error('Não foi possível carregar a verificação. Confira sua conexão e recarregue a página.'));};
      document.head.append(script);
    });return loading;
  }
  async function show(mode){
    const seq=++sequence;clear();if(widget!==null){api().remove(widget);widget=null;}
    const needed=config.enabled&&mode!=='change';el('captcha-block').hidden=!needed;
    if(!needed){el('auth-submit').disabled=false;return;}
    if(!['hcaptcha','turnstile'].includes(config.provider)||!config.siteKey){message('O acesso à conta está sendo configurado. Tente novamente mais tarde.');return;}
    message('Carregando verificação…');
    try{
      await load();if(seq!==sequence)return;
      const container=el('captcha-widget');
      if(!container)throw new Error('Não foi possível preparar a verificação. Reabra o formulário.');
      widget=api().render(container,{
        sitekey:config.siteKey,theme:'light',size:window.innerWidth<400?'compact':'normal',
        callback:value=>{if(seq!==sequence)return;token=value;el('auth-submit').disabled=false;message('');},
        'expired-callback':()=>{if(seq!==sequence)return;clear();message('A verificação expirou. Confirme novamente.');},
        'error-callback':()=>{if(seq!==sequence)return true;clear();message('Não foi possível verificar. Reabra o formulário para tentar novamente.');return true;}
      });message('');
    }catch(error){message(error.message);}
  }
  window.TerraCaptcha={show,load,
    value:mode=>{if(!config.enabled||mode==='change')return undefined;if(!token)throw new Error('Conclua a verificação de segurança antes de continuar.');return token;},
    reset:()=>{clear();if(widget!==null)api().reset(widget);},
    close:()=>{++sequence;clear();if(widget!==null){api().remove(widget);widget=null;}}
  };
})();
